export type LiveExecutionControlSnapshot = (
  | {
      action?: "reconcile";
      status?: "reconciled";
      query_attempted?: true;
      cancel_attempted?: false;
      cancel_confirmed?: false;
      manual_review_required?: false;
      error_code?: null;
    }
  | {
      action?: "reconcile";
      status?: "unknown_manual_review";
      cancel_attempted?: false;
      cancel_confirmed?: false;
      manual_review_required?: true;
      error_code?: string;
    }
  | {
      action?: "cancel";
      status?: "cancel_confirmed";
      exchange_order_status?: "canceled";
      query_attempted?: true;
      cancel_attempted?: true;
      cancel_confirmed?: true;
      manual_review_required?: false;
      error_code?: null;
    }
  | {
      action?: "cancel";
      status?: "cancel_sent_readback_pending";
      query_attempted?: true;
      cancel_attempted?: true;
      cancel_confirmed?: false;
      manual_review_required?: true;
      error_code?: null;
    }
  | {
      action?: "cancel";
      status?: "cancel_not_required_terminal_or_pending";
      exchange_order_status?:
        | "filled"
        | "canceled"
        | "expired"
        | "rejected"
        | "pending_cancel"
        | "pending_update";
      query_attempted?: true;
      cancel_attempted?: false;
      cancel_confirmed?: false;
      manual_review_required?: false;
      error_code?: null;
    }
  | {
      action?: "cancel";
      status?: "unknown_manual_review";
      cancel_confirmed?: false;
      manual_review_required?: true;
      error_code?: string;
    }
) & {
  schema_version: "ntpro.s3.live_execution_control_result.v1";
  request_sha256: ContentHash;
  request_id: string;
  action: "reconcile" | "cancel";
  run_id: RunId;
  admission_id: string;
  strategy_version_id: StrategyVersionId;
  instrument_id: string;
  client_order_id: string;
  venue_order_id: string | null;
  status:
    | "reconciled"
    | "cancel_confirmed"
    | "cancel_sent_readback_pending"
    | "cancel_not_required_terminal_or_pending"
    | "unknown_manual_review";
  exchange_order_status: string | null;
  original_quantity: string | null;
  filled_quantity: string | null;
  remaining_quantity: string | null;
  query_attempted: boolean;
  cancel_attempted: boolean;
  cancel_confirmed: boolean;
  automatic_retry_attempted: false;
  manual_review_required: boolean;
  error_code: string | null;
  completed_at_unix_ms: number;
};

